---@class MultiSelectView : ViewBase
MultiSelectView = class("MultiSelectView", ViewBase)

function MultiSelectView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "MultiSelectViewAction")
end
local isUseArticle=false
function MultiSelectView:Awake()
    isUseArticle=false
    self.Center = UIUtil.GetChild("Center", self.gameObject)
    self.shownum = UIUtil.GetChild("shownum", self.Center)

    CommonHelper:HButtonSetCallback("BtnCloseMask", self.Center, function(data)
        UIManager:Get():ClosePopup()
    end)
    CommonHelper:HButtonSetCallback("BtnClose", self.Center, function(data)
        UIManager:Get():ClosePopup()
    end)

    CommonHelper:HButtonSetCallback("BtnSure", self.Center, function(hbtn)
        self:OnEnsureBtnClick()
    end)

    CommonHelper:HButtonSetCallback("BtnEditorRemove", self.Center, function(hbtn)
        self:OnClickBtn_Num(-1)
    end)

    CommonHelper:HButtonSetCallback("BtnEditorAdd", self.Center, function(hbtn)
        self:OnClickBtn_Num(1)
    end)

    CommonHelper:HButtonSetCallback("BtnEditorMax", self.Center, function(hbtn)
        self:OnClickBtn_Num(__AddMax)
    end)
    CommonHelper:HButtonSetCallback("BtnEditorMin", self.Center, function(data)
        self:OnClickBtn_Num(-__AddMax)
    end)

    self.Input = UIUtil.GetTypeChildWightInputPath("UseNumInput", self.Center, typeof(InputField))

    self.Input.onValueChanged:AddListener(function(str)
        if CommonHelper:IsNullOrEmpty(str) then
            return
        end
        local result = tonumber(str)
        if result then
            __AddNum = result
            __AddNum = __AddNum < 1 and 1 or __AddNum
            __AddNum = __AddNum > __AddMax and __AddMax or __AddNum
            CommonHelper:SetInputFieldTextByGo(self.Input,  __AddNum)
        end
    end)
end

function MultiSelectView:OnEnsureBtnClick()
    local NoPosition = WelfareBoxDataManager:Get():GetBoxLocData()
    print("--518, --请求打开宝箱 P2=位置 P3=宝箱id", NoPosition, _id)
    BoxAwardSubsystem:Get():SendMsg_ReqOpenBox(NoPosition, _id,__AddNum)
    UIManager:Get():ClosePopup()
end

function MultiSelectView:OnClose()

end
---@param data
function MultiSelectView:SetData(data)
    __AddNum = 0

    if data~=nil then
        _id = data[1]
        _count = data[2]
    end
    __AddMax = 1000
    __AddMax =__AddMax>_count and _count or __AddMax
    local obj = UIUtil.GetChild("ItemCom_202", self.Center)
    CommonHelper:SetItemComGroup(obj, UIModuleID.Welfare, _id)
    ---@type dictparts_config_cell
    local partData = CommonHelper:GetTableDataByID(ConfigNames.parts_config, _id)
    local articleData = CommonHelper:GetTableDataByID(ConfigNames.article_config, _id)
    ---@type tracksegement_config_cell
    local trackData = CommonHelper:GetTableDataByID(ConfigNames.tracksegement_config, _id)
    local desc = ""
    if partData ~= nil then
        desc = CommonHelper:GetTempStr_Default(partData.partdesc)
    end
    if articleData ~= nil or trackData~=nil then
        if articleData then
            desc= CommonHelper:GetTempStr_Default(articleData.description)
        end
        if trackData then
            desc=CommonHelper:GetTempStr_Default(trackData.desc)
        end
    end
    local propType,cfg= CommonHelper:GetPropTypeById(_id)
    local name=""
    if propType == PropType.Part then
        name = CommonHelper:GetTempStr_Default(cfg.partname)
    elseif propType == PropType.Article then
        name  = CommonHelper:GetTempStr_Default(cfg.name)
    elseif propType == PropType.TracKSegment then
        name  = CommonHelper:GetTempStr_Default(cfg.name)
    end
    CommonHelper:SetText("###name",self.Center,name)
    CommonHelper:SetText("###hasnum", self.Center, _count)
    CommonHelper:SetText("###desctext", self.Center, desc)
    self:OnClickBtn_Num(__AddNum)
end

function MultiSelectView:SetCost()
    CommonHelper:SetInputFieldTextByGo(self.Input,  __AddNum)

    --CommonHelper:SetText("###PropPriceText", self.Root, string.format(CommonHelper:GetTempStr_Default(TemplateStringID.NumComNum), __AddNum, __AddMax))
end

function MultiSelectView:OnClickBtn_Num(num)
    __AddNum = __AddNum + num

    __AddNum = __AddNum < 1 and 1 or __AddNum
    __AddNum = __AddNum > __AddMax and __AddMax or __AddNum

    self:SetCost()
end

